from __future__ import annotations

from typing import TYPE_CHECKING

import json
from urllib.parse import urlparse, parse_qs

if TYPE_CHECKING:
    from requests import Response

from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.tracer import tracer


class EventsMethods(BaseClient):
    """
    Методы группы 'События' из https://im-docs.corp.mail.ru/
    """

    @tracer.start_as_current_span("events.get_event_stream")
    def get_event_stream(self, timeout: int = 600):
        response = self.request(method="GET", url=self.fetch_url, stream=True, timeout=timeout)

        try:
            events = []
            response_json = None

            for response_json in self.yield_streaming_response(response):
                self.logger.info(f"eventsStream chunk: {response_json}")
                self.fetch_url = response_json["response"]["data"]["fetchBaseURL"]
                events.extend(response_json["response"]["data"]["events"])

            response_json["response"]["data"]["events"] = events
            self.logger.info(response_json)

            return response_json
        except Exception as error:
            self.logger.exception(error)
            raise error

    @tracer.start_as_current_span("events.bos_fetchEvents")
    def bos_fetchEvents(self, rewrite: bool = True, timeout: int = 600):
        """
        Первичный урл для fetch запроса выдается в ответе на startSession.
        :return: тело ответа сервера
        """
        if self.fetch_url is None:
            raise ValueError("/bos/fetchEvents url is None")

        if "eventsStream" in self.fetch_url:
            return self.get_event_stream(timeout=timeout)

        else:
            parsed_url = urlparse(self.fetch_url)

            query: dict[str, str | int | list[str | int]] = parse_qs(parsed_url.query)

            for key, value in query.copy().items():
                if len(value) == 1:
                    query[key] = value[0]

            if rewrite:
                query["timeout"] = timeout

            result = self.request(
                method="GET",
                url="{url.scheme}://{url.netloc}{url.path}".format(url=parsed_url),
                params=query,
            )
            if "fetchBaseURL" in result["response"]["data"]:
                self.fetch_url = result["response"]["data"]["fetchBaseURL"]

                parsed_url = urlparse(self.fetch_url)
                query = parse_qs(parsed_url.query)

                assert self.aimsid == query["aimsid"][-1], f"{self.env}:FetchEvents aimsid not equal to main aimsid"

            return result

    @staticmethod
    @tracer.start_as_current_span("events.yield_streaming_response")
    def yield_streaming_response(response: Response):
        content = response.content

        counter = 0
        prev_counter = 0
        index = []
        open_index = 0

        for i, symb in enumerate(response.iter_content()):
            try:
                if symb.decode("utf-8") == "{":
                    counter += 1
                elif symb.decode("utf-8") == "}":
                    counter -= 1
                else:
                    continue

                if counter == 1 and prev_counter == 0:
                    open_index = i
                elif counter == 0 and prev_counter == 1:
                    index.append([open_index, i + 1])
                prev_counter = counter

            except (json.JSONDecodeError, UnicodeDecodeError):
                continue

        for x, y in index:
            yield json.loads(content[x:y].decode("utf-8"))

    @tracer.start_as_current_span("events.bos_eventsStream")
    def bos_eventsStream(
        self,
        first: int = 1,
        hotstart: int = 1,
        hotstartAck: int = 1,
        seqNum: int = 1,
        hidden: int = 0,
        supportedSuggestTypes: str = "sticker-smartreply",
    ):
        """
        В отличие от fetchEvents, в eventsStream клиент в одном HTTP
        запросе получит множество ответов. Если клиент сделает еще
        один запрос, то передача событий в предыдущем запросе прекратится.

        В ответе от сервера указан заголовок
        "Content-Type: application/octet-stream".

        Перед каждым ответом, сервер посылает размер ответа
        в 4 байтах в big endian order, за ними следует тело ответа.
        Тело ответа может быть сжато, но размер не сжимается никогда.

        Добавлено новое событие ackRequired для подтвержения
        получения других событий и проверки доступности соединения.
        Сервер отправляет ackRequired вместе с histDlgState,
        а так же по таймеру.
        При наличии нескольких histDlgState в одном ответе,
        ackRequired будет только один.
        В hotstart запросах ackRequired не отправляется.

        Клиенту необходимо перейти по ackURL из ackRequired,
        чтобы подтвердить получение событий.
        Если от клиента не было подтверждений,
        то по истечении таймаута сервер закроет соединение.

        Так же клиенту необходимо передать "7d552c211af3414b932db31a65e01b0a"
        в assertCaps в startSession для использования eventsStream.
        """
        return self.get(
            "bos/eventsStream",
            aimsid=self.aimsid,
            first=first,
            hotstart=hotstart,
            hotstartAck=hotstartAck,
            seqNum=seqNum,
            hidden=hidden,
            supportedSuggestTypes=supportedSuggestTypes,
        )

    @tracer.start_as_current_span("events.bos_ackEvents")
    def bos_ackEvents(self, path: str, seqNum: int = 1):
        """
        Метод, используемый для подтверждения получения события клиентом.
        Инициируется сервером, путем отправки события ackRequired.
        :param path:
        :param seqNum: Идентификатор версии события
        :return: тело ответа сервера
        """
        return self.post(path, params={"aimsid": self.aimsid, "seqNum": seqNum})
